async function stockAction(action,payload={}) {
  const response=await request('life_stock_fast_requests',{args:{action,payload:JSON.stringify(payload)},csrfToken:session.csrf_token});
  const result=response?.message;
  if (!result || result.ok===false) throw new Error(result?.message||'Stock service returned an invalid response.');
  return result;
}
async function loadContext() {
