      isHo.value?stockAction('invoke',{method:'frappe.client.get_list',args:{doctype:'Stock Ledger Entry',fields:['item_code'],filters:{company:context.value?.company||'Life Slimming And Cosmetic Pvt Ltd',posting_date:['>=',inputDate(dateFrom)],actual_qty:['!=',0],is_cancelled:0},limit_page_length:20000}}):Promise.resolve({data:[]})
    ]);
