  try {
    const doctypeFields={Supplier:['name','supplier_name','supplier_group','supplier_type','disabled','on_hold','email_id','mobile_no','country'], 'Purchase Order':['name','transaction_date','schedule_date','supplier','supplier_name','status','workflow_state','docstatus','grand_total','total_qty','per_received','per_billed','currency'], 'Purchase Receipt':['name','posting_date','supplier','supplier_name','supplier_delivery_note','status','docstatus','grand_total','total_qty','currency'], 'Purchase Invoice':['name','posting_date','due_date','supplier','supplier_name','status','workflow_state','docstatus','grand_total','outstanding_amount','currency']};
