const filteredProcurement = (doctype) => (procurementData.value[doctype]||[]).filter(row=>`${row.name} ${row.supplier_name||''} ${row.supplier||''} ${row.status||''} ${row.workflow_state||''}`.toLowerCase().includes(procurementQuery.value.trim().toLowerCase()));
async function procurementWorkflow(doctype,name,action){
  if(!window.confirm(`${action} ${doctype} ${name}? ERPNext will validate linked documents and permissions.`))return;
  busy.value=true;error.value='';actionMessage.value='';
  try{
    let result;
    if(action==='Send for Approval'||action==='Approve'||action==='Reject'){
      const doc=await getDocument(doctype,name);const transitions=await stockAction('invoke',{method:'frappe.model.workflow.get_transitions',args:{doc}});const available=transitions.data||[];const transition=available.find(row=>row.action===action)||(action==='Send for Approval'?available.find(row=>/send.*approval/i.test(row.action)):null);if(!transition)throw new Error(`The ${action} workflow transition is unavailable for this document or account.`);result=await stockAction('invoke',{method:'frappe.model.workflow.apply_workflow',args:{doc,action:transition.action}});
    }else if(action==='Submit'){
      const doc=await getDocument(doctype,name);if(Number(doc.docstatus)!==0)throw new Error('Only a draft document can be submitted.');result=await stockAction('invoke',{method:'frappe.client.submit',args:{doc}});
    }else if(action==='Cancel'){
      const doc=await getDocument(doctype,name);if(Number(doc.docstatus)!==1)throw new Error('Only a submitted document can be cancelled.');result=await stockAction('invoke',{method:'frappe.client.cancel',args:{doctype,name}});
    }
    actionMessage.value=`${doctype} ${name}: ${action} completed.`;await loadProcurement();
  }catch(cause){error.value=cause.message||`Could not ${action.toLowerCase()} ${doctype}.`;}
  finally{busy.value=false;}
}
async function loadProcurementTransitions(doctype,name){
  busy.value=true;error.value='';
  try{const doc=await getDocument(doctype,name);const response=await stockAction('invoke',{method:'frappe.model.workflow.get_transitions',args:{doc}});procurementTransitions.value={...procurementTransitions.value,[`${doctype}:${name}`]:response.data||[]};if(!(response.data||[]).length)actionMessage.value=`No workflow action is currently available for ${name}.`;}
  catch(cause){error.value=cause.message||'Could not load available document actions.';}
  finally{busy.value=false;}
}
