function setPurchaseReportPreset(preset){
  const today=new Date(),dateOnly=value=>inputDate(value),start=new Date(today.getFullYear(),today.getMonth(),today.getDate()),end=new Date(start);
  if(preset==='Yesterday'){start.setDate(start.getDate()-1);end.setTime(start.getTime());}
  else if(preset==='This Week'){start.setDate(start.getDate()-((start.getDay()+6)%7));}
  else if(preset==='This Month'){start.setDate(1);}
  else if(preset==='3 Months'){start.setMonth(start.getMonth()-3);}
  else if(preset==='6 Months'){start.setMonth(start.getMonth()-6);}
  else if(preset==='1 Year'){start.setFullYear(start.getFullYear()-1);}
  purchaseReportFrom.value=dateOnly(start);purchaseReportTo.value=dateOnly(end);runPurchaseReport();
}
