function exportBalance() {
  const cols=reportColumns.value.map(col=>col.label||col.fieldname||'');
  const quote=value=>'"'+String(value??'').replaceAll('"','""')+'"';
  const csv=[cols.map(quote).join(','),...filteredReportRows.value.map(row=>reportColumns.value.map(col=>quote(row[col.fieldname])).join(','))].join('\r\n');
  const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.download='stock-balance.csv';link.click();URL.revokeObjectURL(link.href);
}
function exportIntelligenceTable(table){
  const quote=value=>'"'+String(value??'').replaceAll('"','""')+'"';const csv=[table.columns.map(col=>quote(col.label||col.fieldname)).join(','),...table.rows.map(row=>table.columns.map((col,index)=>quote(Array.isArray(row)?row[index]:row[col.fieldname])).join(','))].join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.download=`stock-intelligence-${table.key}.csv`;link.click();URL.revokeObjectURL(link.href);
}
onMounted(()=>{refresh();loadClusterHeads().then(rows=>{clusterHeads.value=rows;});loadMonthlyIndentAccess();clockTimer=window.setInterval(()=>{currentTime.value=new Date();},1000);});
onBeforeUnmount(()=>{controller?.abort();if(clockTimer)window.clearInterval(clockTimer);});
</script>

<template>
  <main class="stock-native">
    <header class="stock-header"><div><span class="stock-eyebrow">LIFE SLIMMING · INVENTORY</span><h1>Stock Management</h1><p>Inventory · Material Requests · Approvals · Procurement</p></div><div class="stock-profile"><span>{{ isHo?'Head Office / Stock Manager':branchName }}</span><strong>{{ context?.employee?.employee_name||context?.user||'Loading user…' }}</strong><button :disabled="loading" @click="refresh">{{ loading?'Refreshing…':'↻ Refresh' }}</button><small>{{ currentTime.toLocaleDateString('en-IN',{weekday:'short',day:'2-digit',month:'short',year:'numeric'}) }} · {{ currentTime.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',second:'2-digit'}) }}</small><a class="stock-legacy-link" href="/life_portal/stores-360">Open Stock 360 ↗</a></div></header>
    <nav class="stock-nav" aria-label="Stock management modules"><button v-for="[id,label] in navItems" :key="id" :class="{active:view===id}" @click="setView(id)">{{ label }}<b v-if="id==='requests'">{{ requestData?.total||0 }}</b></button></nav>
    <div v-if="error" class="stock-error" role="alert">{{ error }} <button @click="error=''">Dismiss</button></div>
    <div v-if="actionMessage" class="stock-success" role="status">{{ actionMessage }}</div>
    <section v-if="view==='dashboard'" class="stock-panel">
      <div class="stock-welcome"><div><h2>{{ isHo?'Head Office dashboard':'Branch stock dashboard' }}</h2><p>{{ isHo?'Review live stock across authorized warehouses, material requests, and stock movements.':`Branch context: ${branchName}. Create and track material requests and stock receipts.` }}</p></div><button v-if="!isHo" class="stock-primary" @click="setView('new-request')">＋ Raise Stock Request</button><button v-else class="stock-primary" @click="setView('requests')">Open approvals →</button></div>
      <div class="stock-cards"><button v-for="[key,label] in [['pending','Pending review'],['approved','Approved / awaiting release'],['released','Released / in transit'],['rejected','Rejected']]" :key="key" @click="requestGroup=key;page=1;setView('requests')"><span>{{ label }}</span><strong>{{ requestCounts[key]||0 }}</strong></button></div>
      <div class="stock-cards"><div><span>Distinct stocked items</span><strong>{{ dashboardStockMetrics.items }}</strong></div><div><span>Total quantity on hand</span><strong>{{ format(dashboardStockMetrics.qty) }}</strong></div><div><span>Zero stock rows</span><strong>{{ dashboardStockMetrics.zero }}</strong></div><div><span>Low stock rows · ≤ 5</span><strong>{{ dashboardStockMetrics.low }}</strong></div><div v-if="isHo"><span>Dead stock · no movement 180 days</span><strong>{{ dashboardStockMetrics.dead }}</strong></div></div>
      <div class="stock-shortcuts"><button @click="setView('new-request')"><strong>📝 Material Request</strong><span>Raise monthly, special, or advance requests</span></button><button @click="setView('requests')"><strong>📥 Requests &amp; Approvals</strong><span>Review and follow request status</span></button><button @click="setView('balance')"><strong>📋 Stock Balance</strong><span>Search and export the ERP stock report</span></button><button @click="setView('checklist')"><strong>✅ Check List</strong><span>Physical verification and approval</span></button></div>
      <div class="stock-panel-head"><div><h2>Live inventory by warehouse</h2><p>{{ dashboardVisibleBins.length }} row(s) match the filters · zero and low stock included</p></div><button :disabled="dashboardInventoryLoading" @click="loadDashboardInventory">{{ dashboardInventoryLoading?'Loading…':'↻ Refresh inventory' }}</button></div>
      <div class="stock-report-controls"><label>Warehouse<select v-model="dashboardWarehouse"><option value="">All authorized warehouses</option><option v-for="warehouse in allowedWarehouses" :key="warehouse" :value="warehouse">{{ warehouse }}</option></select></label><label>Category<select v-model="dashboardCategory"><option value="">All categories</option><option v-for="category in dashboardCategories" :key="category">{{ category }}</option></select></label><label>Status<select v-model="dashboardStatus"><option value="">All stock states</option><option>Zero Stock</option><option>Low Stock</option><option v-if="isHo">Dead Stock</option><option>Normal</option></select></label><label>Search<input v-model="dashboardQuery" type="search" placeholder="Item, code, category, warehouse"></label></div>
      <p v-if="dashboardInventoryLoading" class="stock-loading">Loading live stock rows…</p><div v-else class="stock-table-wrap"><table><thead><tr><th>Item code</th><th>Item</th><th>Category</th><th>Warehouse</th><th>On hand</th><th>Projected</th><th>Rate</th><th>Actions</th></tr></thead><tbody><tr v-for="row in dashboardVisibleBins.slice(0,500)" :key="row.warehouse+':'+row.item_code"><td>{{ row.item_code }}</td><td>{{ row.item_name||row.item_code }}</td><td>{{ row.item_group||'—' }}</td><td>{{ row.warehouse }}</td><td>{{ format(row.actual_qty) }}</td><td>{{ format(row.projected_qty) }}</td><td>{{ format(row.valuation_rate) }}</td><td><button class="stock-link" @click="openItemEditor(row.item_code)">Item details</button></td></tr><tr v-if="!dashboardVisibleBins.length"><td colspan="8" class="stock-empty">No stock rows match these filters.</td></tr></tbody></table></div><p v-if="dashboardVisibleBins.length>500" class="stock-footnote">Showing first 500 of {{ dashboardVisibleBins.length }} matching rows. Use filters to narrow the list.</p>
      <p class="stock-note">{{ context?.allowed_warehouses?.length||0 }} warehouses available to your account · {{ context?.roles?.join(', ')||'Role information unavailable' }}</p>
    </section>
    <section v-else-if="view==='new-request'" class="stock-panel"><div class="stock-panel-head"><div><h2>Raise a Stock Request</h2><p>Raise monthly, special material, or advance material requests with the required supporting documents.</p></div><button @click="setView('requests')">View requests</button></div><div class="stock-form-grid"><label>Request type<select v-model="requestForm.type" @change="onRequestTypeChange"><option>Monthly Indent Request</option><option>Special Material Request</option><option>Advance Material Request</option></select></label><label>Request date<input v-model="requestForm.date" type="date"></label><label>Required by<input v-model="requestForm.needBy" type="date" :min="requestForm.date" :max="requestForm.type==='Special Material Request'?(selectedSpecialAppointmentRow?.appointment_date||''):undefined"></label><label>Source warehouse<input value="Stores - LSACPL" disabled></label><label>Target branch warehouse<select v-model="requestForm.target" @change="requestForm.type==='Monthly Indent Request'?loadMonthlyIndentAvailability(requestForm.target):loadRequestStockAvailability(requestForm.target)"><option value="">Choose target</option><option v-for="warehouse in allowedWarehouses" :key="warehouse" :value="warehouse">{{ warehouse }}</option></select></label><p v-if="requestForm.type!=='Monthly Indent Request'&&requestForm.target" class="stock-note stock-form-wide">{{ requestStockLoading?'Checking target stock…':'Target stock availability is shown on each selected item.' }} <button :disabled="requestStockLoading" @click="loadRequestStockAvailability(requestForm.target)">Refresh availability</button></p><div class="stock-form-wide"><template v-if="requestForm.type==='Monthly Indent Request'"><h3>Bulk Monthly Indent · Active MONTHLY INDENT items</h3><p>Enter whole Required Qty values from 1 to 999. Availability is calculated for the selected target warehouse.</p><div class="stock-report-controls"><label>Search items<input v-model="monthlyIndentQuery" type="search" placeholder="Name or item code"></label><button :disabled="monthlyIndentLoading" @click="loadMonthlyIndentItems">↻ Refresh approved item list</button></div><p v-if="monthlyIndentLoading" class="stock-loading">Loading monthly indent items and stock…</p><div v-else class="stock-table-wrap"><table><thead><tr><th>Item code</th><th>Item name</th><th>Available at target</th><th>Required qty</th></tr></thead><tbody><tr v-for="row in monthlyIndentVisible" :key="row.item_code"><td>{{ row.item_code }}</td><td>{{ row.item_name }}<small>{{ row.stock_uom }}</small></td><td>{{ format(row.available_qty) }}</td><td><input v-model.number="row.required_qty" type="number" min="0" max="999" step="1"></td></tr><tr v-if="!monthlyIndentVisible.length"><td colspan="4" class="stock-empty">No active monthly indent items match.</td></tr></tbody></table></div><div class="stock-pager"><button :disabled="monthlyIndentPage<=1" @click="monthlyIndentPage--">Previous</button>Page {{ monthlyIndentPage }} of {{ monthlyIndentPages }} · {{ monthlyIndentMatches.length }} item(s)<button :disabled="monthlyIndentPage>=monthlyIndentPages" @click="monthlyIndentPage++">Next</button></div><label><input v-model="monthlyIndentDeclarations.monthly" type="checkbox"> I confirm this is a bulk monthly indent request.</label><label><input v-model="monthlyIndentDeclarations.consumption" type="checkbox"> I confirm the items are for general branch consumption and records will be maintained.</label></template><template v-else-if="requestForm.type==='Special Material Request'"><h3>Configured consumables for selected therapy services</h3><p>Only enabled stock items configured on the selected therapy type can be added.</p><div v-for="item in selectedSpecialConsumables" :key="item.therapy_type+'::'+item.name" class="stock-count-line"><span>{{ item.item_name||item.name }} · {{ item.therapy_type }} · valuation {{ format(item.valuation_rate) }}</span><label>Quantity<input v-model.number="item.qty" type="number" min="0" step="any"></label><small>{{ requestItemAvailable(item.name) }} available at target</small></div><p v-if="selectedSpecialTherapies.length&&!selectedSpecialConsumables.length" class="stock-empty">No configured stock consumables were found for this therapy service.</p></template><template v-else><h3>Requested items</h3><div v-for="(line,index) in requestLines" :key="index" class="stock-count-line"><label>Stock item<select v-model="line.item" :disabled="itemLoading||requestForm.type==='Special Material Request'&&!selectedSpecialAppointment"><option value="">{{ itemLoading?'Loading items…':requestForm.type==='Special Material Request'&&!selectedSpecialAppointment?'Choose the appointment first':'Choose item' }}</option><option v-for="item in itemChoices" :key="item.name" :value="item.name">{{ item.item_name||item.name }} · {{ item.name }} · {{ item.stock_uom||'' }}</option></select></label><small v-if="requestForm.type==='Special Material Request'">{{ requestItemAvailable(line.item) }} available at target</small><label>Quantity<input v-model.number="line.qty" type="number" min="0.001" step="any"></label><button v-if="requestLines.length>1" @click="requestLines.splice(index,1)">Remove</button></div><button @click="addRequestLine">＋ Add stock item</button></template></div><label v-if="requestForm.type==='Special Material Request'" class="stock-client-field">Search branch client<input v-model="specialClientQuery" autocomplete="off" placeholder="Client name, ID, or mobile" @input="searchSpecialClients"><span v-if="specialClientLoading">Searching clients…</span><button v-for="patient in specialClientRows" :key="patient.name" type="button" class="stock-employee-option" @click="selectSpecialClient(patient)">{{ patient.patient_name||patient.name }} · {{ patient.name }} · {{ patient.mobile||'No mobile' }}</button><small v-if="selectedSpecialClient">Selected client: {{ selectedSpecialClient.patient_name||selectedSpecialClient.name }} · {{ selectedSpecialClient.name }}</small></label><label v-else-if="requestForm.type==='Advance Material Request'">Expected client<input v-model="requestForm.clientName"></label><label v-if="requestForm.type!=='Monthly Indent Request'">Client phone<input v-model="requestForm.clientPhone" type="tel"></label><label v-if="requestForm.type!=='Monthly Indent Request'">Treatment category<input v-model="requestForm.treatment"></label><label v-if="requestForm.type==='Advance Material Request'">Expected joining date<input v-model="requestForm.joinDate" type="date" :min="requestForm.date"></label><label v-if="requestForm.type==='Advance Material Request'">Expected sessions<input v-model.number="requestForm.sessions" type="number" min="0" step="1"></label><label v-if="requestForm.type==='Advance Material Request'">Existing LIFE client<select v-model="requestForm.existingClient"><option value="">Choose</option><option>Yes</option><option>No</option></select></label><label v-if="requestForm.type==='Advance Material Request'&&requestForm.existingClient==='Yes'">Previous branch<input v-model="requestForm.previousBranch"></label><label v-if="requestForm.type==='Advance Material Request'&&requestForm.existingClient==='No'">Recent walk-in client<select v-model="requestForm.recentWalkIn"><option value="">Choose</option><option>Yes</option><option>No</option></select></label><div v-if="requestForm.type==='Advance Material Request'" class="stock-form-wide"><label>Requesting employee (active branch employee)<input v-model="advanceEmployeeQuery" autocomplete="off" placeholder="Search by employee name or ID" @input="searchAdvanceEmployees"><span v-if="advanceEmployeeLoading">Searching employees…</span><button v-for="employee in advanceEmployeeRows" :key="employee.name" type="button" class="stock-employee-option" @click="selectAdvanceEmployee(employee)">{{ employee.employee_name||employee.name }} · {{ employee.name }}</button><small v-if="selectedAdvanceEmployee">Selected: {{ selectedAdvanceEmployee.employee_name||selectedAdvanceEmployee.name }} · {{ selectedAdvanceEmployee.name }}</small></label><label>Sales Cluster Head<select v-model="requestForm.clusterHead"><option value="">Choose cluster head</option><option v-for="leader in clusterHeads" :key="leader.name" :value="leader.name">{{ leader.employee_name||leader.name }}</option></select></label></div><label v-if="requestForm.type==='Special Material Request'">Future patient appointment<select v-model="selectedSpecialAppointment" :disabled="!selectedSpecialClient||specialAppointmentLoading" @change="selectedSpecialTherapies=[]"><option value="">{{ specialAppointmentLoading?'Loading appointments…':'Choose appointment' }}</option><option v-for="appointment in specialAppointments" :key="appointment.name" :value="appointment.name">{{ appointment.name }} · {{ date(appointment.appointment_date) }} {{ appointment.appointment_time||'' }} · {{ appointment.therapy_type1||appointment.therapy_type||appointment.concern||'Therapy' }}</option></select></label><div v-if="requestForm.type==='Special Material Request'&&selectedSpecialClient" class="stock-form-wide"><h3>Remaining therapy services <small v-if="specialTherapyLoading">Loading…</small></h3><p>{{ specialRemainingSessions }} sessions remain across {{ specialTherapyRows.length }} therapy detail row(s). Only choose a service matched to the selected appointment.</p><div class="stock-cards compact"><div><span>Linked invoices paid</span><strong>{{ format(specialTherapyFinance.paid) }}</strong></div><div><span>Linked invoices outstanding</span><strong>{{ format(specialTherapyFinance.due) }}</strong></div></div><div v-for="row in appointmentTherapyRows" :key="row.therapy_plan+'::'+row.therapy_detail_row" class="stock-release-form"><label><input v-model="selectedSpecialTherapies" type="checkbox" :value="row.therapy_plan+'::'+row.therapy_detail_row"> {{ row.therapy_type }} · Plan {{ row.therapy_plan }} · {{ row.remaining_sessions }} remaining ({{ row.completed_sessions }}/{{ row.booked_sessions }} used)<small v-if="row.stock_eligible_sessions===0">No unused paid sessions verified</small></label></div><p v-if="selectedSpecialAppointment&&!appointmentTherapyRows.length&&!specialTherapyLoading" class="stock-empty">No remaining therapy service matches this appointment.</p><template v-if="selectedSpecialTherapies.length"><h4>Estimated configured consumables: {{ format(specialConsumableTotal) }}</h4><label v-if="specialTherapyRows.filter(row=>selectedSpecialTherapies.includes(`${row.therapy_plan}::${row.therapy_detail_row}`)&&row.stock_eligible_sessions===0)"><input v-model="specialPaymentException" type="checkbox"> I confirm an exception request despite no unused paid session</label><label v-if="specialPaymentException">Exception reason<select v-model="specialExceptionReason"><option value="">Choose reason</option><option>Stock Issue / System Error</option><option>Approved by Branch Head</option><option>Emergency Treatment</option><option>Other Reason</option></select></label><label v-if="specialExceptionReason==='Other Reason'">Other exception details<input v-model="specialExceptionOther"></label></template></div><label v-if="requestForm.type!=='Monthly Indent Request'" class="stock-form-wide">Supporting files · {{ requestForm.type==='Special Material Request'?'2 required':'1 required' }}<input type="file" multiple @change="setRequestAttachments"></label><label class="stock-form-wide">Additional notes<textarea v-model="requestForm.notes" rows="3"></textarea></label><label v-if="requestForm.type==='Advance Material Request'" class="stock-form-wide">Instructions for Store Manager<textarea v-model="requestForm.instructions" rows="2"></textarea></label><template v-if="requestForm.type==='Advance Material Request'"><label class="stock-form-wide"><input v-model="advanceDeclarations.cluster" type="checkbox"> Sales Cluster Head approval has been obtained</label><label class="stock-form-wide"><input v-model="advanceDeclarations.stock" type="checkbox"> Requested items are unavailable at the branch</label><label class="stock-form-wide"><input v-model="advanceDeclarations.records" type="checkbox"> Client and treatment records will be maintained</label><label class="stock-form-wide"><input v-model="advanceDeclarations.responsibility" type="checkbox"> Branch accepts stock handling responsibility</label></template></div><p v-if="requestForm.type!=='Monthly Indent Request'">{{ requestAttachments.length }} supporting file(s) selected.</p><div class="stock-form-actions"><button class="stock-primary" :disabled="busy||itemLoading" @click="submitMonthlyRequest">{{ busy?'Submitting…':requestForm.type==='Monthly Indent Request'?'Submit Monthly Indent Request':requestForm.type==='Special Material Request'?'Submit Special Material Request':'Submit Advance Material Request' }}</button><button @click="setView('requests')">Cancel</button></div></section>
    <section v-else-if="view==='requests'" class="stock-panel"><div class="stock-panel-head"><div><h2>{{ isHo?'Requests & Approvals':'My Branch Material Requests' }}</h2><p>{{ isHo?'Material requests from authorized branches. Review approval quantities before confirming.':'Material request status and receipt progress for your branch.' }}</p></div><button :disabled="loading" @click="loadRequests">↻ Refresh</button></div><div class="stock-cards compact"><button v-for="[key,label] in [['all','All'],['pending','Pending'],['approved','Approved'],['released','Released'],['rejected','Rejected']]" :key="key" :class="{selected:requestGroup===key}" @click="requestGroup=key;page=1;loadRequests()"><span>{{ label }}</span><strong>{{ key==='all'?requestData?.total||0:requestCounts[key]||0 }}</strong></button></div><label class="stock-search">Search requests<input v-model="requestQuery" type="search" placeholder="Request number, branch, item, status"></label><p v-if="loading" class="stock-loading" role="status">Loading material requests…</p><div class="stock-table-wrap"><table><thead><tr><th>Request</th><th>Requested</th><th>Branch / target</th><th>Request type</th><th>Items</th><th>Status</th><th>Actions</th></tr></thead><tbody><template v-for="row in visibleRequests" :key="row.name"><tr><td><button class="stock-link" @click="toggleRequest(row.name)">{{ row.name }}</button><small>{{ row.title||'' }}</small></td><td>{{ date(row.transaction_date||row.creation) }}</td><td>{{ row.set_warehouse||row.branch||'—' }}</td><td>{{ row.custom_stock_request_type||row.material_request_type||'—' }}</td><td>{{ rowItems(row).length }}</td><td><span class="stock-status">{{ row.workflow_state||row.custom_stock_request_status||row.status||row._group }}</span></td><td><button v-if="isHo&&row._group==='pending'" :disabled="busy" @click="runApproval(row)">Approve quantities</button><button v-if="isHo&&row._group==='pending'" :disabled="busy" @click="runReject(row)">Reject</button><button v-if="isHo&&row._group==='approved'" @click="initRelease(row)">{{ selectedRelease===row.name?'Close release':'Release stock' }}</button><button @click="toggleRequest(row.name)">{{ expanded===row.name?'Hide':'Details' }}</button></td></tr><tr v-if="expanded===row.name" class="stock-detail"><td colspan="7"><div class="stock-table-wrap"><table><thead><tr><th>Item</th><th>Description</th><th>Requested qty</th><th>Approved qty</th><th>Released qty</th><th>Received qty</th><th>Pending</th></tr></thead><tbody><tr v-for="(item,index) in rowItems(row)" :key="item.name||index"><td>{{ item.item_code||item.item }}</td><td>{{ item.item_name||item.description||'—' }}</td><td>{{ format(item.qty) }} {{ item.uom||'' }}</td><td><input v-if="isHo&&row._group==='pending'" v-model.number="approvalQty[row.name][item.name||item.item_code]" type="number" min="0" :max="item.qty" step="any"><span v-else>{{ format(item.custom_approved_qty??item.approved_qty) }}</span></td><td>{{ format(item.released_qty) }}</td><td>{{ format(item.received_qty??item.custom_received_qty) }}</td><td>{{ format(item.pending_qty) }}</td></tr></tbody></table></div><div v-if="selectedRelease===row.name" class="stock-release-form"><h3>Release approved stock</h3><div class="stock-form-grid"><label>Sending method<select v-model="releaseDrafts[row.name].method"><option value="">Choose method</option><option>Rapido Bike</option><option>Courier</option><option>By OM</option><option>By Store Manager</option><option>By Bus Courier</option><option>By Flight</option></select></label><label>Delivery / tracking reference<input v-model="releaseDrafts[row.name].reference" placeholder="Rider name, tracking number, or reference"></label><label>Delivery challan photo<input type="file" accept="image/*" multiple @change="setReleaseFiles(row.name,$event)"></label><label class="stock-form-wide">Release remarks<textarea v-model="releaseDrafts[row.name].remarks" rows="2"></textarea></label></div><p>{{ (releaseFiles[row.name]||[]).length }} image(s) selected · at least one required</p><button class="stock-primary" :disabled="busy" @click="releaseRequest(row)">{{ busy?'Releasing…':'Release stock & submit transfer' }}</button></div><p>Source: {{ row.set_from_warehouse||'—' }} · Need by: {{ date(row.schedule_date) }} · Requester: {{ row.requester_name||row.owner||'—' }}</p><label v-if="isHo&&row._group==='pending'" class="stock-search">Stock Manager remarks<textarea v-model="approvalRemarks[row.name]" rows="2"></textarea></label><p v-if="row.custom_store_manager_instructions">Manager instructions: {{ row.custom_store_manager_instructions }}</p></td></tr></template><tr v-if="!loading&&!visibleRequests.length"><td colspan="7" class="stock-empty">No requests match this filter.</td></tr></tbody></table></div><div v-if="requestData" class="stock-pager"><button :disabled="page<=1||loading" @click="page--;loadRequests()">Previous</button>Page {{ requestData.page }} of {{ requestData.total_pages }} · {{ requestData.total }} request(s)<button :disabled="page>=requestData.total_pages||loading" @click="page++;loadRequests()">Next</button></div></section>
    <section v-else-if="view==='balance'" class="stock-panel"><div class="stock-panel-head"><div><h2>Stock Balance</h2><p>Live ERP Stock Balance report with search, paging, CSV export, and permission-aware item editing.</p></div><button :disabled="reportLoading" @click="loadStockBalance">{{ reportLoading?'Loading…':'↻ Refresh report' }}</button></div><div class="stock-report-controls"><label>From<input v-model="reportFrom" type="date"></label><label>To<input v-model="reportTo" type="date"></label><button class="stock-primary" :disabled="reportLoading" @click="loadStockBalance">Run report</button><label>Search<input v-model="reportQuery" type="search" placeholder="Filter report rows"></label><button :disabled="!reportRows.length" @click="exportBalance">Export CSV</button></div><p v-if="reportLoading" class="stock-loading">Loading Stock Balance…</p><div v-else-if="reportData?.message" class="stock-error">{{ reportData.message }}</div><div v-else-if="reportColumns.length" class="stock-table-wrap"><table><thead><tr><th v-for="col in reportColumns" :key="col.fieldname">{{ col.label }}</th><th>Item</th></tr></thead><tbody><tr v-for="(row,index) in pagedReportRows" :key="row.name||index"><td v-for="col in reportColumns" :key="col.fieldname">{{ format(row[col.fieldname]) }}</td><td><button v-if="row.item_code||row.item" class="stock-link" @click="openItemEditor(row.item_code||row.item)">Edit item</button></td></tr><tr v-if="!pagedReportRows.length"><td :colspan="reportColumns.length+1" class="stock-empty">No stock rows found.</td></tr></tbody></table></div><p v-if="reportColumns.length" class="stock-pager"><button :disabled="reportPage<=1" @click="reportPage--">Previous</button>Page {{ reportPage }} of {{ totalReportPages }}<button :disabled="reportPage>=totalReportPages" @click="reportPage++">Next</button></p></section>
    <section v-else-if="view==='receipts'" class="stock-panel"><div class="stock-panel-head"><div><h2>Branch Stock Receipt Updates</h2><p>Record quantities physically received for open Material Transfer entries.</p></div><button :disabled="receiptLoading" @click="loadReceipts">↻ Refresh</button></div><p v-if="receiptLoading" class="stock-loading">Loading receipt entries…</p><div v-for="entry in receiptRows" :key="entry.name" class="stock-receipt-card"><div class="stock-panel-head"><div><h3>{{ entry.name }}</h3><p>{{ entry.from_warehouse||'—' }} → {{ entry.to_warehouse||'—' }} · {{ date(entry.posting_date) }} · {{ entry.workflow_state||'Draft' }}</p><p>Released by {{ entry.released_by||'—' }} · {{ entry.custom_delivery_reference||'No delivery reference' }}</p></div><button @click="selectedReceipt=selectedReceipt===entry.name?'':entry.name">{{ selectedReceipt===entry.name?'Close receipt':'Enter received quantities' }}</button></div><div v-if="selectedReceipt===entry.name"><div class="stock-table-wrap"><table><thead><tr><th>Item</th><th>Released qty</th><th>Received qty</th><th v-if="receiptDiscrepancyMode">Missing qty</th><th v-if="receiptDiscrepancyMode">Damaged qty</th><th>Source</th></tr></thead><tbody><tr v-for="item in entry.items||[]" :key="item.name"><td>{{ item.item_name||item.item_code }}<small>{{ item.item_code }}</small></td><td>{{ format(item.qty) }} {{ item.uom||'' }}</td><td><input v-model.number="receiptQty[item.name]" type="number" min="0" :max="item.qty" step="any"></td><td v-if="receiptDiscrepancyMode"><input v-model.number="receiptMissing[item.name]" type="number" min="0" :max="item.qty" step="any"></td><td v-if="receiptDiscrepancyMode"><input v-model.number="receiptDamaged[item.name]" type="number" min="0" :max="item.qty" step="any"></td><td>{{ item.s_warehouse||'—' }}</td></tr></tbody></table></div><div class="stock-form-grid"><label class="stock-employee-field">Receiving employee<input v-model="receiptEmployeeQuery" autocomplete="off" placeholder="Search employee name or ID" @input="searchReceiptEmployees"><small v-if="receiptEmployeeName">Selected: {{ receiptEmployeeName }} · {{ receiptEmployee }}</small><span v-if="receiptEmployeeLoading">Searching…</span><button v-for="employee in receiptEmployeeRows" :key="employee.name" type="button" class="stock-employee-option" @click="selectReceiptEmployee(employee)">{{ employee.employee_name }} · {{ employee.name }} · {{ employee.designation||'Employee' }}</button></label><label class="stock-form-wide">{{ receiptDiscrepancyMode?'Discrepancy remarks (required for missing/damaged items)':'Receipt remarks' }}<textarea v-model="receiptRemarks" rows="2"></textarea></label></div><button v-if="!receiptDiscrepancyMode" class="stock-primary" :disabled="busy" @click="confirmReceipt(entry)">{{ busy?'Saving…':'Confirm & submit receipt' }}</button><button v-if="!receiptDiscrepancyMode" @click="receiptDiscrepancyMode=true">Report missing / damaged</button><button v-if="receiptDiscrepancyMode" class="stock-primary" :disabled="busy" @click="submitReceiptDiscrepancy(entry)">{{ busy?'Submitting…':'Submit discrepancy for review' }}</button><button v-if="receiptDiscrepancyMode" @click="receiptDiscrepancyMode=false">Back to receipt confirmation</button></div></div><div v-if="!receiptLoading&&!receiptRows.length" class="stock-empty large">No open branch receipts were returned for this account.</div></section>
    <section v-else-if="view==='stores360'" class="stock-panel stock-embedded-stores"><div class="stock-panel-head"><div><h2>Indent, Stock &amp; Item / Vendor 360</h2><p>Vue reports for live inventory, movement, supplier performance, item and vendor detail, and purchase planning.</p></div></div><Stores360NativePage /></section>
    <section v-else-if="view==='intelligence'" class="stock-panel"><div class="stock-panel-head"><div><h2>Stock Intelligence</h2><p>Live ERP inventory, projected stock, ledger movement, asset, batch, and forecast reports.</p></div><button :disabled="intelligenceLoading" @click="loadIntelligence">{{ intelligenceLoading?'Loading…':'↻ Refresh' }}</button></div><div class="stock-report-controls"><label>From<input v-model="intelligenceFrom" type="date"></label><label>To<input v-model="intelligenceTo" type="date"></label><button class="stock-primary" :disabled="intelligenceLoading" @click="loadIntelligence">Run reports</button><label>Warehouse<select v-model="intelligenceWarehouse"><option value="">All Head Office warehouses</option><option v-for="warehouse in allowedWarehouses" :key="warehouse" :value="warehouse">{{ warehouse }}</option></select></label><label>Search reports<input v-model="intelligenceQuery" type="search" placeholder="Item, client, therapy, warehouse"></label></div><div class="stock-cards compact"><div><span>Items in stock report</span><strong>{{ format(intelligenceStockSummary.items) }}</strong></div><div><span>Quantity</span><strong>{{ format(intelligenceStockSummary.qty) }}</strong></div><div><span>Stock value</span><strong>{{ format(intelligenceStockSummary.value) }}</strong></div><div><span>Batch rows</span><strong>{{ format(intelligenceStockSummary.batches) }}</strong></div></div><div class="stock-cards compact"><div><span>Projected shortage rows</span><strong>{{ format(intelligenceProjectedSummary.shortages) }}</strong></div><div><span>Projected shortage qty</span><strong>{{ format(intelligenceProjectedSummary.shortage) }}</strong></div><div><span>Assets</span><strong>{{ format(intelligenceAssetSummary.count) }}</strong></div><div><span>Asset purchase value</span><strong>{{ format(intelligenceAssetSummary.value) }}</strong></div></div><section v-if="intelligenceMovementTop.length" class="stock-top-items"><h3>Largest outbound movement · last 4 months</h3><div v-for="row in intelligenceMovementTop" :key="row.item_code+'::'+row.warehouse" class="stock-top-item"><span>{{ row.item_code }} · {{ row.warehouse }}</span><div><i :style="{width:`${Math.max(4,100*row._out/Math.max(1,intelligenceMovementTop[0]._out))}%`}"></i></div><strong>{{ format(row._out) }} / {{ format(row._value) }}</strong></div></section><section v-if="intelligenceTopStock.length" class="stock-top-items"><h3>Highest reported stock value</h3><div v-for="row in intelligenceTopStock" :key="row.item_code+'::'+row.warehouse" class="stock-top-item"><span>{{ row.item_name||row.item_code }} · {{ row.warehouse||'—' }}</span><div><i :style="{width:`${Math.max(4,100*row._value/Math.max(1,intelligenceTopStock[0]._value))}%`}"></i></div><strong>{{ format(row._value) }}</strong></div></section><p v-if="intelligenceLoading" class="stock-loading" role="status">Loading Stock Intelligence reports…</p><div v-for="table in intelligenceTables" :key="table.key" class="stock-intel-table"><div class="stock-panel-head"><h3>{{ table.key.replaceAll(/([A-Z])/g,' $1').replaceAll('_',' ') }} · {{ table.rows.length }}</h3><button :disabled="!table.rows.length" @click="exportIntelligenceTable(table)">Export CSV</button></div><div class="stock-table-wrap"><table><thead><tr><th v-for="field in table.columns" :key="field.fieldname">{{ field.label||field.fieldname }}</th></tr></thead><tbody><tr v-for="(row,index) in table.rows" :key="row.item_code||row.warehouse||index"><td v-for="(field,columnIndex) in table.columns" :key="field.fieldname">{{ format(Array.isArray(row)?row[columnIndex]:row[field.fieldname]) }}</td></tr><tr v-if="!table.rows.length"><td :colspan="Math.max(1,table.columns.length)" class="stock-empty">No rows match this warehouse and search.</td></tr></tbody></table></div></div><ul v-if="intelligenceFailed.length" class="stock-warnings"><li v-for="message in intelligenceFailed" :key="message">{{ message }}</li></ul><p v-if="!intelligenceLoading&&!intelligenceTables.length" class="stock-empty large">No report rows returned. Choose a date range and run Stock Intelligence.</p><p class="stock-footnote">Vue tables and summaries powered by the Stock Intelligence API.</p></section>
    <section v-else-if="view==='adjustments'" class="stock-panel"><div class="stock-panel-head"><div><h2>Branch Receipt Discrepancies</h2><p>Review missing and damaged quantities and apply the approved correction to inventory.</p></div><button :disabled="adjustmentLoading" @click="loadAdjustments">↻ Refresh</button></div><p v-if="adjustmentLoading" class="stock-loading">Loading adjustment requests…</p><div class="stock-table-wrap"><table><thead><tr><th>Adjustment</th><th>Stock Entry</th><th>Branch</th><th>Reported by / date</th><th>Released</th><th>Received</th><th>Missing</th><th>Damaged</th><th>Status</th><th>Remarks</th><th>Actions</th></tr></thead><tbody><tr v-for="row in adjustmentRows" :key="row.name"><td>{{ row.name }}</td><td>{{ row.stock_entry }}</td><td>{{ row.target_branch||'—' }}</td><td>{{ row.reported_by_name||'—' }}<small>{{ date(row.reported_on) }}</small></td><td>{{ format(row.total_released_qty) }}</td><td>{{ format(row.total_received_qty) }}</td><td>{{ format(row.total_missing_qty) }}</td><td>{{ format(row.total_damaged_qty) }}</td><td><span class="stock-status">{{ row.status }}</span></td><td>{{ row.branch_receipt_remarks||row.stock_manager_remarks||'—' }}</td><td><button v-if="isHo&&['Pending Stock Manager Approval','Correction Requested'].includes(row.status)" :disabled="busy" @click="adjustmentDecision(row,'approve')">Approve & apply</button><button v-if="isHo&&row.status==='Pending Stock Manager Approval'" :disabled="busy" @click="adjustmentDecision(row,'correction')">Request correction</button><button v-if="isHo&&row.status==='Pending Stock Manager Approval'" :disabled="busy" @click="adjustmentDecision(row,'reject')">Reject</button></td></tr><tr v-if="!adjustmentLoading&&!adjustmentRows.length"><td colspan="11" class="stock-empty">No receipt discrepancy requests found.</td></tr></tbody></table></div></section>
    <section v-else-if="view==='checklist'" class="stock-panel"><div class="stock-panel-head"><div><h2>Physical Stock Check List</h2><p>Create a counted stock reconciliation and track manager approval.</p></div><button :disabled="reconciliationLoading" @click="loadReconciliations">↻ Refresh</button></div><div class="stock-form-grid"><label>Warehouse<select v-model="reconciliationForm.warehouse"><option value="">Choose warehouse</option><option v-for="warehouse in allowedWarehouses" :key="warehouse" :value="warehouse">{{ warehouse }}</option></select></label><label>Posting date<input v-model="reconciliationForm.date" type="date"></label><div class="stock-form-wide"><h3>Physical counts</h3><div v-for="(line,index) in reconciliationItems" :key="index" class="stock-count-line"><label>Item<select v-model="line.item_code" @focus="loadRequestItems"><option value="">Choose item</option><option v-for="item in itemChoices" :key="item.name" :value="item.name">{{ item.item_name||item.name }} · {{ item.name }}</option></select></label><label>Warehouse<select v-model="line.warehouse"><option value="">Use selected warehouse</option><option v-for="warehouse in allowedWarehouses" :key="warehouse" :value="warehouse">{{ warehouse }}</option></select></label><label>Physical quantity<input v-model.number="line.qty" type="number" min="0" step="any"></label><label>Valuation rate<input v-model.number="line.valuation_rate" type="number" min="0" step="any"></label></div><button @click="addReconciliationLine">＋ Add count line</button></div></div><div class="stock-form-actions"><button class="stock-primary" :disabled="busy" @click="createReconciliation">{{ busy?'Submitting…':'Submit for Stock Manager Approval' }}</button></div><div class="stock-report-controls"><label>Search<input v-model="reconciliationQuery" type="search" placeholder="Name, warehouse, owner"></label><label>Status<select v-model="reconciliationStatus"><option value="all">All statuses</option><option>Pending Stock Manager Approval</option><option>Approved</option><option>Rejected</option><option>Submitted</option></select></label></div><p v-if="reconciliationLoading" class="stock-loading" role="status">Loading verification records…</p><div class="stock-table-wrap"><table><thead><tr><th>Reconciliation</th><th>Date</th><th>Warehouse</th><th>Workflow status</th><th>Difference amount</th><th>Created by</th><th>Actions</th></tr></thead><tbody><tr v-for="row in filteredReconciliations" :key="row.name"><td>{{ row.name }}</td><td>{{ date(row.posting_date) }}</td><td>{{ row.set_warehouse }}</td><td><span class="stock-status">{{ row.workflow_state }}</span></td><td>{{ format(row.difference_amount) }}</td><td>{{ row.owner||'—' }}</td><td><button @click="toggleReconciliationDetail(row)">{{ reconciliationDetails[row.name]?.open?'Hide lines':'View lines' }}</button><button v-if="isHo&&row.workflow_state==='Pending Stock Manager Approval'" :disabled="busy" @click="reconciliationWorkflow(row,'Approve')">Approve & submit</button><button v-if="isHo&&row.workflow_state==='Pending Stock Manager Approval'" :disabled="busy" @click="reconciliationWorkflow(row,'Reject')">Reject</button></td></tr><tr v-if="!reconciliationLoading&&!filteredReconciliations.length"><td colspan="7" class="stock-empty">No physical stock verification records match the filters.</td></tr></tbody></table></div><section v-for="detail in Object.values(reconciliationDetails).filter(entry=>entry.open&&entry.items)" :key="detail.name" class="stock-release-form"><h3>{{ detail.name }} · counted items</h3><div class="stock-table-wrap"><table><thead><tr><th>Item</th><th>Warehouse</th><th>Current qty</th><th>Counted qty</th><th>Difference</th><th>Valuation rate</th><th>Amount difference</th></tr></thead><tbody><tr v-for="item in detail.items" :key="item.name"><td>{{ item.item_name||item.item_code }}<small>{{ item.item_code }}</small></td><td>{{ item.warehouse }}</td><td>{{ format(item.current_qty) }} {{ item.stock_uom }}</td><td>{{ format(item.qty) }}</td><td>{{ format(item.quantity_difference) }}</td><td>{{ format(item.valuation_rate) }}</td><td>{{ format(item.amount_difference) }}</td></tr></tbody></table></div></section></section>
    <section v-else-if="view==='reports'" class="stock-panel"><div class="stock-panel-head"><div><h2>Stock Reports</h2><p>Run ERPNext reports for inventory quantity and movements.</p></div><button :disabled="reportLoading" @click="runSelectedReport">{{ reportLoading?'Running…':'Run report' }}</button></div><section v-if="isStockManager" class="stock-release-form"><h3>Purchasing and supplier reports</h3><div class="stock-nav"><button v-for="[key,label] in [['recent-orders','Recent Orders'],['recent-payments','Recent Payments'],['recent-receipts','Recent Receipts'],['blocked','Blocked Suppliers'],['active','Active Suppliers']]" :key="key" :class="{active:purchaseReportTab===key}" @click="purchaseReportTab=key;runPurchaseReport()">{{ label }}</button></div><div v-if="! ['blocked','active'].includes(purchaseReportTab)" class="stock-report-controls"><button v-for="preset in ['Today','Yesterday','This Week','This Month','3 Months','6 Months','1 Year']" :key="preset" @click="setPurchaseReportPreset(preset)">{{ preset }}</button></div><div class="stock-report-controls"><label v-if="!['blocked','active'].includes(purchaseReportTab)">From<input v-model="purchaseReportFrom" type="date"></label><label v-if="!['blocked','active'].includes(purchaseReportTab)">To<input v-model="purchaseReportTo" type="date"></label><label v-if="!['blocked','active'].includes(purchaseReportTab)">Supplier ID<input v-model="purchaseReportSupplier" placeholder="All suppliers"></label><label v-if="['recent-orders','recent-payments'].includes(purchaseReportTab)">Minimum amount<input v-model.number="purchaseReportMin" type="number" min="0"></label><label v-if="['recent-orders','recent-payments'].includes(purchaseReportTab)">Maximum amount<input v-model.number="purchaseReportMax" type="number" min="0"></label><button class="stock-primary" :disabled="purchaseReportLoading" @click="runPurchaseReport">{{ purchaseReportLoading?'Loading…':'Search' }}</button></div><p v-if="purchaseReportLoading" class="stock-loading">Loading report records…</p><div v-else class="stock-table-wrap"><table><thead><tr><th>Record</th><th>{{ ['blocked','active'].includes(purchaseReportTab)?'Supplier / group':'Supplier / party' }}</th><th>Date</th><th>{{ purchaseReportTab==='recent-payments'?'Paid amount':purchaseReportTab==='recent-receipts'?'Total qty':'Grand total' }}</th><th>Status / details</th></tr></thead><tbody><tr v-for="row in filteredPurchaseReportRows" :key="row.name"><td>{{ row.name }}</td><td>{{ row.supplier_name||row.supplier||row.party||row.supplier_group||'—' }}</td><td>{{ date(row.transaction_date||row.posting_date) }}</td><td>{{ format(row.paid_amount??row.grand_total??row.total_qty) }}</td><td>{{ row.workflow_state||row.status||(row.disabled?'Blocked':row.on_hold?'On Hold':'Active') }}<span v-if="row.mode_of_payment"> · {{ row.mode_of_payment }}</span><span v-if="row.supplier_type"> · {{ row.supplier_type }}</span></td></tr><tr v-if="!filteredPurchaseReportRows.length"><td colspan="5" class="stock-empty">No matching report records.</td></tr></tbody></table></div></section><div class="stock-report-controls"><label>Report<select v-model="stockReportName"><option>Stock Balance</option><option>Stock Projected Qty</option><option>Stock Ledger</option></select></label><label>From<input v-model="reportFrom" type="date"></label><label>To<input v-model="reportTo" type="date"></label><label>Search<input v-model="reportQuery" type="search" placeholder="Filter report rows"></label><button :disabled="!reportRows.length" @click="exportBalance">Export CSV</button></div><p v-if="reportLoading" class="stock-loading">Running {{ stockReportName }}…</p><div v-if="reportColumns.length" class="stock-table-wrap"><table><thead><tr><th v-for="col in reportColumns" :key="col.fieldname">{{ col.label }}</th></tr></thead><tbody><tr v-for="(row,index) in pagedReportRows" :key="row.name||index"><td v-for="col in reportColumns" :key="col.fieldname">{{ format(row[col.fieldname]) }}</td></tr><tr v-if="!pagedReportRows.length"><td :colspan="reportColumns.length" class="stock-empty">No report rows.</td></tr></tbody></table></div><p v-if="reportColumns.length" class="stock-pager"><button :disabled="reportPage<=1" @click="reportPage--">Previous</button>Page {{ reportPage }} of {{ totalReportPages }}<button :disabled="reportPage>=totalReportPages" @click="reportPage++">Next</button></p></section>
    <section v-else-if="view==='procurement'" class="stock-panel"><div class="stock-panel-head"><div><h2>Purchase Orders, Receipts & Invoices</h2><p>Create and review ERP purchasing documents from the Stock dashboard.</p></div><div><button :disabled="procurementLoading" @click="loadProcurement">↻ Refresh</button> <button class="stock-primary" @click="showPOForm=!showPOForm;loadRequestItems()">＋ New Purchase Order</button></div></div><p v-if="procurementLoading" class="stock-loading">Loading purchasing records…</p><section v-if="showPOForm" class="stock-release-form"><h3>Create Purchase Order</h3><div class="stock-form-grid"><label>Supplier<select v-model="poForm.supplier"><option value="">Choose supplier</option><option v-for="supplier in supplierRows" :key="supplier.name" :value="supplier.name">{{ supplier.supplier_name||supplier.name }}</option></select></label><label>Transaction date<input v-model="poForm.date" type="date"></label><label>Schedule date<input v-model="poForm.schedule" type="date"></label><div class="stock-form-wide"><h3>Items</h3><div v-for="(row,index) in poForm.rows" :key="index" class="stock-count-line"><label>Item<select v-model="row.item"><option value="">Choose item</option><option v-for="item in itemChoices" :key="item.name" :value="item.name">{{ item.item_name||item.name }} · {{ item.name }}</option></select></label><label>Quantity<input v-model.number="row.qty" type="number" min="0.001" step="any"></label><label>Rate<input v-model.number="row.rate" type="number" min="0" step="any"></label><label>Receiving warehouse<select v-model="row.warehouse"><option value="">Choose warehouse</option><option v-for="warehouse in allowedWarehouses" :key="warehouse" :value="warehouse">{{ warehouse }}</option></select></label><button v-if="poForm.rows.length>1" @click="poForm.rows.splice(index,1)">Remove line</button></div><button @click="poForm.rows.push({item:'',qty:1,rate:0,warehouse:''})">＋ Add item line</button></div></div><button class="stock-primary" :disabled="busy" @click="createPurchaseOrder">{{ busy?'Creating…':'Create Purchase Order' }}</button></section><section v-if="receiptForm.purchaseOrder" class="stock-release-form"><h3>Create Purchase Receipt from {{ receiptForm.purchaseOrder }}</h3><div class="stock-form-grid"><label>Posting date<input v-model="receiptForm.date" type="date"></label><label>Warehouse<select v-model="receiptForm.warehouse"><option value="">Choose warehouse</option><option v-for="warehouse in allowedWarehouses" :key="warehouse" :value="warehouse">{{ warehouse }}</option></select></label></div><div v-for="row in receiptForm.rows" :key="row.purchase_order_item" class="stock-count-line"><strong>{{ row.item_name }} · {{ row.item_code }}</strong><label>Qty to receive<input v-model.number="row.qty" type="number" min="0" step="any"></label><label>Rate<input v-model.number="row.rate" type="number" min="0" step="any"></label><label>Warehouse<input v-model="row.warehouse"></label></div><button class="stock-primary" :disabled="busy" @click="createPurchaseReceipt">{{ busy?'Creating…':'Create Draft Purchase Receipt' }}</button><button @click="receiptForm.purchaseOrder=''">Cancel</button></section><section v-if="invoiceForm.source" class="stock-release-form"><h3>Create Purchase Invoice from {{ invoiceForm.source }}</h3><div class="stock-form-grid"><label>Invoice source<select v-model="invoiceForm.sourceType" @change="invoiceForm.source='';invoiceForm.rows=[]"><option>Purchase Order</option><option>Purchase Receipt</option></select></label><label>Source document<select v-model="invoiceForm.source" @change="prepareInvoice(invoiceForm.sourceType,invoiceForm.source)"><option :value="invoiceForm.source">{{ invoiceForm.source }}</option><option v-for="row in procurementData[invoiceForm.sourceType]||[]" :key="row.name" :value="row.name">{{ row.name }} · {{ row.supplier_name||row.supplier }}</option></select></label><label>Posting date<input v-model="invoiceForm.date" type="date"></label><label>Supplier invoice no.<input v-model="invoiceForm.billNo"></label><label>Supplier invoice date<input v-model="invoiceForm.billDate" type="date"></label></div><div v-for="row in invoiceForm.rows" :key="row.source_item" class="stock-count-line"><strong>{{ row.item_name }} · {{ row.item_code }}</strong><label>Qty to bill<input v-model.number="row.qty" type="number" min="0" step="any"></label><label>Rate<input v-model.number="row.rate" type="number" min="0" step="any"></label><label>Warehouse<input v-model="row.warehouse"></label></div><button class="stock-primary" :disabled="busy" @click="createPurchaseInvoice">{{ busy?'Creating…':'Create Draft Purchase Invoice' }}</button><button @click="invoiceForm.source=''">Cancel</button></section><label class="stock-search">Filter purchasing documents<input v-model="procurementQuery" type="search" placeholder="Document, supplier, status"></label><div v-for="[doctype,title] in [['Purchase Order','Purchase Orders'],['Purchase Receipt','Purchase Receipts'],['Purchase Invoice','Purchase Invoices']]" :key="doctype" class="stock-intel-table"><h3>{{ title }} · {{ procurementData[doctype]?.length||0 }}</h3><div class="stock-table-wrap"><table><thead><tr><th>Document</th><th>Date</th><th>Supplier</th><th>Status</th><th>Amount</th><th v-if="doctype==='Purchase Invoice'">Outstanding</th><th>Actions</th></tr></thead><tbody><tr v-for="row in filteredProcurement(doctype)" :key="row.name"><td>{{ row.name }}</td><td>{{ date(row.transaction_date||row.posting_date) }}</td><td>{{ row.supplier_name||row.supplier }}</td><td>{{ row.status }}</td><td>{{ format(row.grand_total) }} {{ row.currency||'' }}</td><td v-if="doctype==='Purchase Invoice'">{{ format(row.outstanding_amount) }}</td><td><button v-if="doctype==='Purchase Order'&&Number(row.docstatus)===1&&!(['Cancelled','Closed','Completed'].includes(row.status))" @click="prepareReceipt(row.name)">Receive</button><button v-if="(doctype==='Purchase Order'&&Number(row.docstatus)===1&&row.workflow_state?.toLowerCase()==='approved'&&Number(row.per_billed||0)<100)||(doctype==='Purchase Receipt'&&Number(row.docstatus)===1&&row.status?.toLowerCase().replaceAll(' ','')==='tobill')" @click="prepareInvoice(doctype,row.name)">Create invoice</button><button v-if="Number(row.docstatus)===0" @click="procurementWorkflow(doctype,row.name,'Submit')">Submit</button><button v-if="Number(row.docstatus)===1" @click="procurementWorkflow(doctype,row.name,'Cancel')">Cancel</button><button v-if="doctype!=='Purchase Receipt'&&Number(row.docstatus)!==2" @click="loadProcurementTransitions(doctype,row.name)">Workflow actions</button><span v-for="transition in procurementTransitions[`${doctype}:${row.name}`]||[]" :key="transition.action"><button @click="procurementWorkflow(doctype,row.name,transition.action)">{{ transition.action }}</button></span><a class="stock-document-link" :href="`/app/${doctype.toLowerCase().replaceAll(' ','-')}/${encodeURIComponent(row.name)}`" target="_blank" rel="noopener">Open ERP doc</a></td></tr></tbody></table></div></div></section>
    <section v-else-if="view==='suppliers'" class="stock-panel"><div class="stock-panel-head"><div><h2>Suppliers</h2><p>Supplier directory and basic supplier details.</p></div><div><button :disabled="procurementLoading" @click="loadProcurement">↻ Refresh</button><button class="stock-primary" @click="supplierEditing=false;supplierFormOpen=true;supplierForm={name:'',supplier_name:'',supplier_group:'',supplier_type:'Company',email_id:'',mobile_no:'',country:'India'}">＋ New Supplier</button></div></div><section v-if="supplierFormOpen" class="stock-release-form"><h3>{{ supplierEditing?'Edit Supplier':'Create Supplier' }}</h3><div class="stock-form-grid"><label>Supplier name<input v-model="supplierForm.supplier_name"></label><label>Supplier group<select v-model="supplierForm.supplier_group"><option value="">Choose supplier group</option><option v-for="group in supplierGroups" :key="group">{{ group }}</option></select></label><label>Supplier type<select v-model="supplierForm.supplier_type"><option>Company</option><option>Individual</option></select></label><label>Email<input v-model="supplierForm.email_id" type="email"></label><label>Mobile<input v-model="supplierForm.mobile_no" type="tel"></label><label>Country<input v-model="supplierForm.country"></label><label class="stock-form-wide"><input v-model="supplierForm.disabled" type="checkbox"> Block / disable supplier</label></div><button class="stock-primary" :disabled="busy" @click="saveSupplier">{{ busy?'Saving…':'Save supplier' }}</button><button @click="supplierFormOpen=false">Cancel</button></section><label class="stock-search">Search supplier<input v-model="supplierQuery" type="search" placeholder="Supplier name or ID"></label><p v-if="procurementLoading" class="stock-loading">Loading supplier directory…</p><div class="stock-table-wrap"><table><thead><tr><th>Supplier</th><th>Supplier group</th><th>Type</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="row in supplierRows.filter(item=>`${item.name} ${item.supplier_name} ${item.supplier_group}`.toLowerCase().includes(supplierQuery.toLowerCase()))" :key="row.name"><td>{{ row.supplier_name||row.name }}<small>{{ row.name }}</small></td><td>{{ row.supplier_group||'—' }}</td><td>{{ row.supplier_type||'—' }}</td><td>{{ row.disabled?'Disabled':'Active' }}</td><td><button @click="editSupplier(row)">Edit</button><button @click="openSupplierDetail(row)">Details &amp; linked records</button><a class="stock-document-link" :href="`/app/supplier/${encodeURIComponent(row.name)}`" target="_blank" rel="noopener">Open ERP doc</a></td></tr><tr v-if="!supplierRows.length"><td colspan="5" class="stock-empty">No suppliers returned.</td></tr></tbody></table></div></section>
    <div v-if="supplierDetail||supplierDetailLoading" class="stock-modal-backdrop" @click.self="supplierDetail=null"><section class="stock-item-modal" role="dialog" aria-modal="true"><div class="stock-panel-head"><div><h2>Supplier details</h2><p>{{ supplierDetail?.supplier?.supplier_name||supplierDetail?.supplier?.name||'Loading…' }}</p></div><button @click="supplierDetail=null">Close</button></div><p v-if="supplierDetailLoading" class="stock-loading">Loading linked supplier records…</p><template v-if="supplierDetail"><div class="stock-cards compact"><div><span>Status</span><strong>{{ supplierDetail.supplier.disabled?'Blocked':supplierDetail.supplier.on_hold?'On Hold':'Active' }}</strong></div><div><span>Group</span><strong>{{ supplierDetail.supplier.supplier_group||'—' }}</strong></div><div><span>Email</span><strong>{{ supplierDetail.supplier.email_id||'—' }}</strong></div><div><span>Mobile</span><strong>{{ supplierDetail.supplier.mobile_no||'—' }}</strong></div></div><h3>Contacts</h3><div v-for="contact in supplierDetail.contacts" :key="contact.name" class="stock-release-form"><strong>{{ contact.first_name }} {{ contact.last_name||'' }}</strong> · {{ contact.designation||'—' }}<p>{{ (contact.phone_nos||[]).map(row=>row.phone).filter(Boolean).join(', ')||'No phone' }} · {{ (contact.email_ids||[]).map(row=>row.email_id).filter(Boolean).join(', ')||'No email' }}</p></div><div v-if="!supplierDetail.contacts.length" class="stock-empty">No linked contacts.</div><h3>Addresses</h3><div v-for="address in supplierDetail.addresses" :key="address.name" class="stock-release-form"><strong>{{ address.address_title }}</strong> · {{ address.address_type }}<p>{{ [address.address_line1,address.address_line2,address.city,address.state,address.pincode,address.country].filter(Boolean).join(', ') }}</p><small>{{ address.gst_category||'' }}</small></div><div v-if="!supplierDetail.addresses.length" class="stock-empty">No linked addresses.</div><div class="stock-form-grid"><label>Contact first name<input v-model="supplierContactForm.first_name"></label><label>Designation<input v-model="supplierContactForm.designation"></label><label>Mobile<input v-model="supplierContactForm.mobile" type="tel"></label><label>Email<input v-model="supplierContactForm.email" type="email"></label></div><button :disabled="busy" @click="saveSupplierLinkedRecord('Contact')">＋ Add contact</button><div class="stock-form-grid"><label>Address type<select v-model="supplierAddressForm.address_type"><option>Billing</option><option>Shipping</option><option>Office</option><option>Warehouse</option><option>Other</option></select></label><label>Address line 1<input v-model="supplierAddressForm.address_line1"></label><label>Address line 2<input v-model="supplierAddressForm.address_line2"></label><label>City<input v-model="supplierAddressForm.city"></label><label>State<input v-model="supplierAddressForm.state"></label><label>Postal code<input v-model="supplierAddressForm.pincode"></label><label>Country<input v-model="supplierAddressForm.country"></label><label>GST category<select v-model="supplierAddressForm.gst_category"><option>Unregistered</option><option>Registered Regular</option><option>Registered Composition</option><option>SEZ</option><option>Overseas</option></select></label></div><button :disabled="busy" @click="saveSupplierLinkedRecord('Address')">＋ Add address</button><h3>Recent invoices</h3><div class="stock-table-wrap"><table><thead><tr><th>Invoice</th><th>Date</th><th>Total</th><th>Outstanding</th><th>Status</th></tr></thead><tbody><tr v-for="invoice in supplierDetail.invoices" :key="invoice.name"><td>{{ invoice.name }}</td><td>{{ date(invoice.posting_date) }}</td><td>{{ format(invoice.grand_total) }}</td><td>{{ format(invoice.outstanding_amount) }}</td><td>{{ invoice.status }}</td></tr><tr v-if="!supplierDetail.invoices.length"><td colspan="5" class="stock-empty">No invoices.</td></tr></tbody></table></div><h3>Payments</h3><div class="stock-table-wrap"><table><thead><tr><th>Payment</th><th>Date</th><th>Amount</th><th>Mode</th><th>Status</th></tr></thead><tbody><tr v-for="payment in supplierDetail.payments" :key="payment.name"><td>{{ payment.name }}</td><td>{{ date(payment.posting_date) }}</td><td>{{ format(payment.paid_amount) }}</td><td>{{ payment.mode_of_payment||'—' }}</td><td>{{ Number(payment.docstatus)===1?'Submitted':'Draft' }}</td></tr><tr v-if="!supplierDetail.payments.length"><td colspan="5" class="stock-empty">No payments.</td></tr></tbody></table></div></template></section></div>
    <section v-else class="stock-panel"><div class="stock-panel-head"><div><h2>Stock Management</h2><p>Choose a Stock module from the navigation above.</p></div><button @click="setView('dashboard')">Go to dashboard</button></div></section>
    <div v-if="itemEditor.open" class="stock-modal-backdrop" @click.self="itemEditor.open=false"><section class="stock-item-modal" role="dialog" aria-modal="true" aria-labelledby="stock-item-title"><div class="stock-panel-head"><div><h2 id="stock-item-title">Stock item details</h2><p>{{ itemEditor.item?.item_code||'Loading item…' }}</p></div><button @click="itemEditor.open=false">Close</button></div><p v-if="itemEditor.loading" class="stock-loading">Loading item…</p><div v-else-if="itemEditor.form" class="stock-form-grid"><label>Item name<input :value="itemEditor.form.item_name" disabled></label><label>Item category<select v-model="itemEditor.form.item_group" :disabled="!itemEditor.canEdit"><option v-for="group in stockItemGroups" :key="group">{{ group }}</option></select></label><label>Subgroup<input v-model="itemEditor.form.custom_sub_group" :disabled="!itemEditor.canEdit"></label><label>Stock unit<select v-model="itemEditor.form.stock_uom" :disabled="!itemEditor.canEdit"><option v-for="uom in stockUoms" :key="uom">{{ uom }}</option></select></label><label>Selling rate<input v-model.number="itemEditor.form.standard_rate" type="number" min="0" step="any" :disabled="!itemEditor.canEdit"></label><label>Valuation rate<input v-model.number="itemEditor.form.valuation_rate" type="number" min="0" step="any" :disabled="!itemEditor.canEdit"></label><label class="stock-form-wide"><input v-model="itemEditor.form.enabled" type="checkbox" :disabled="!itemEditor.canEdit"> Item enabled</label></div><p v-if="!itemEditor.canEdit&&!itemEditor.loading" class="stock-footnote">Your account can view this item but does not have permission to save item changes.</p><div class="stock-form-actions"><button v-if="itemEditor.canEdit" class="stock-primary" :disabled="itemEditor.saving" @click="saveItemEditor">{{ itemEditor.saving?'Saving…':'Save item' }}</button><button @click="itemEditor.open=false">Close</button></div></section></div>
